const path = require('path');
const fs = require('fs').promises;
const crypto = require('crypto');

// Configuration
const UPLOAD_DIR = '/var/app/uploads';
const PROCESSING_DIR = '/var/app/processing';
const OUTPUT_DIR = '/var/app/output';
const ALLOWED_EXTENSIONS = ['.txt', '.csv', '.json', '.xml', '.log'];

// Unicode-aware filename sanitizer
class FilenameSanitizer {
  constructor() {
    this.dangerousPatterns = [
      /\.\.[\/\\]/g,    // path traversal
      /[<>:"|?*]/g,      // Windows reserved chars
      /[\x00-\x1f]/g,   // control characters
    ];
  }

  sanitize(filename) {
    // Step 1: NFKC normalize to decompose compatibility characters FIRST
    let safe = filename.normalize('NFKC');

    // Step 2: Remove dangerous patterns
    for (const pattern of this.dangerousPatterns) {
      safe = safe.replace(pattern, '');
    }

    // Step 3: Collapse multiple dots to single
    safe = safe.replace(/\.{2,}/g, '.');

    // Step 4: Trim leading/trailing dots and spaces
    safe = safe.replace(/^[\s.]+|[\s.]+$/g, '');

    return safe;
  }
}

// Extension validator
function validateExtension(filename) {
  const ext = path.extname(filename).toLowerCase();
  return ALLOWED_EXTENSIONS.includes(ext);
}

// Path safety check - ensures resolved path is within allowed directory
function isPathSafe(filePath, allowedBase) {
  const resolved = path.resolve(filePath);
  const base = path.resolve(allowedBase);
  return resolved.startsWith(base + path.sep) || resolved === base;
}

// Job processor class
class UploadWorker {
  constructor() {
    this.sanitizer = new FilenameSanitizer();
    this.jobQueue = [];
  }

  async processJob(job) {
    const { originalFilename, uploadId, userId } = job;

    // Sanitize the filename
    const sanitizedName = this.sanitizer.sanitize(originalFilename);

    if (!sanitizedName || sanitizedName.length === 0) {
      throw new Error('Invalid filename after sanitization');
    }

    // Validate extension
    if (!validateExtension(sanitizedName)) {
      throw new Error(`Disallowed file extension: ${path.extname(sanitizedName)}`);
    }

    // Generate processing path with user isolation
    const userDir = path.join(PROCESSING_DIR, userId);
    const processingPath = path.join(userDir, sanitizedName);

    // Verify path safety
    if (!isPathSafe(processingPath, PROCESSING_DIR)) {
      throw new Error('Path traversal detected');
    }

    // Move file from upload to processing
    const sourcePath = path.join(UPLOAD_DIR, uploadId);

    // Verify the source path (derived from untrusted uploadId) stays within UPLOAD_DIR
    if (!isPathSafe(sourcePath, UPLOAD_DIR)) {
      throw new Error('Invalid upload identifier');
    }

    await fs.mkdir(userDir, { recursive: true });
    await fs.copyFile(sourcePath, processingPath);

    // Process the file
    const result = await this.transformFile(processingPath, userId, sanitizedName);

    // Cleanup
    await fs.unlink(processingPath);

    return result;
  }

  async transformFile(filePath, userId, filename) {
    const content = await fs.readFile(filePath, 'utf8');

    // Apply NFKC normalization to content for consistent processing
    const normalizedContent = content.normalize('NFKC');

    // Generate output filename - already NFKC normalized from sanitizer
    const outputName = this.generateOutputName(filename, userId);
    const outputPath = path.join(OUTPUT_DIR, userId, outputName);

    // Final path check on output
    if (!isPathSafe(outputPath, OUTPUT_DIR)) {
      throw new Error('Output path traversal detected');
    }

    await fs.mkdir(path.join(OUTPUT_DIR, userId), { recursive: true });
    await fs.writeFile(outputPath, normalizedContent, 'utf8');

    return { outputPath, size: normalizedContent.length };
  }

  generateOutputName(filename, userId) {
    // Filename already NFKC-normalized from sanitizer, use as-is
    const hash = crypto.createHash('sha256')
      .update(userId + Date.now().toString())
      .digest('hex')
      .slice(0, 8);

    const ext = path.extname(filename);
    const base = path.basename(filename, ext);
    return `${base}_${hash}${ext}`;
  }
}

// Background job runner
async function runWorker() {
  const worker = new UploadWorker();

  // Simulate receiving jobs from queue
  const testJob = {
    originalFilename: process.argv[2] || 'test.txt',
    uploadId: process.argv[3] || 'upload_001',
    userId: process.argv[4] || 'user_123'
  };

  try {
    const result = await worker.processJob(testJob);
    console.log('Job completed:', result);
  } catch (err) {
    console.error('Job failed:', err.message);
  }
}

module.exports = { UploadWorker, FilenameSanitizer, validateExtension, isPathSafe };

if (require.main === module) {
  runWorker();
}
